/** @brief Checks whether a registry solid has baked edges.
 * @param solid Solid registry ordinal.
 * @return Whether an edge index is available. */
constexpr bool supports_baked_sphere_tiling_edges(unsigned solid) {
  using namespace baked_tiling_detail;
  switch (solid) {
  case TRUNCATED_ICOSAHEDRON_SOLID:
  case TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_SOLID:
  case DODECAHEDRON_HK54_AMBO_HK72_SOLID:
    return true;
  default:
    return false;
  }
}

/** @brief Selects the baked edge geometry for a registry solid.
 * @param solid Solid registry ordinal.
 * @return View of constant edge data, or an empty view. */
inline SphereTilingEdgeView baked_sphere_tiling_edges(unsigned solid) {
  using namespace baked_tiling_detail;
  switch (solid) {
  case TRUNCATED_ICOSAHEDRON_SOLID:
    return {TRUNCATED_ICOSAHEDRON_VERTICES, TRUNCATED_ICOSAHEDRON_EDGES,
            TRUNCATED_ICOSAHEDRON_OFFSETS, TRUNCATED_ICOSAHEDRON_CANDIDATES,
            TRUNCATED_ICOSAHEDRON_STEPS};
  case TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_SOLID:
    return {TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_VERTICES,
            TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_EDGES,
            TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_OFFSETS,
            TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_CANDIDATES,
            TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_STEPS,
            {TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_NARROW_CELLS,
             TRUNCATED_ICOSAHEDRON_TRUNCATE50D_AMBO_DUAL_NARROW_CANDIDATES}};
  case DODECAHEDRON_HK54_AMBO_HK72_SOLID:
    return {DODECAHEDRON_HK54_AMBO_HK72_VERTICES,
            DODECAHEDRON_HK54_AMBO_HK72_EDGES,
            DODECAHEDRON_HK54_AMBO_HK72_OFFSETS,
            DODECAHEDRON_HK54_AMBO_HK72_CANDIDATES,
            DODECAHEDRON_HK54_AMBO_HK72_STEPS,
            {DODECAHEDRON_HK54_AMBO_HK72_NARROW_CELLS,
             DODECAHEDRON_HK54_AMBO_HK72_NARROW_CANDIDATES}};
  default:
    return {};
  }
}

